package com.crosscheck.controller;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.*;import org.springframework.beans.BeanUtils;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;import org.springframework.web.server.ResponseStatusException;import java.util.stream.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.core.type.TypeReference;
@RestController @RequestMapping("/api/candidates") public class CandidateController{
 private final CandidateRepository repo;private final DocumentRepository docs;private final AuthService auth;private final RiskEngineService risk;private final AuditService audit;private final EmailService emailService;private final ObjectMapper objectMapper;@Value("${crosscheck.upload-dir}") private String uploadDir;
 public CandidateController(CandidateRepository r,DocumentRepository d,AuthService a,RiskEngineService e,AuditService l,EmailService mail,ObjectMapper mapper){repo=r;docs=d;auth=a;risk=e;audit=l;emailService=mail;objectMapper=mapper;}
 @GetMapping public List<Candidate> all(@RequestHeader(value="Authorization",required=false)String h,@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="")String risk){auth.require(h);String q=search.toLowerCase();return repo.findAllByOrderByCreatedAtDesc().stream().filter(c->risk.isBlank()||risk.equalsIgnoreCase(c.getRiskLevel())).filter(c->q.isBlank()||String.join(" ",n(c.getName()),n(c.getEmail()),n(c.getPosition()),n(c.getSkills())).toLowerCase().contains(q)).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){auth.require(h);Candidate c=repo.findById(id).orElseThrow();Map<String,Object> m=objectMapper.convertValue(c, new TypeReference<Map<String,Object>>(){});m.put("documents",docs.findByCandidateIdOrderByUploadedAtDesc(id));Map<String,Object> factors=new LinkedHashMap<>();factors.put("Duplicate Profile",c.isDuplicateEmail()||c.isDuplicateMobile()?"Detected":"Clear");factors.put("Multiple Offers",c.getActiveOffers());factors.put("Employment Gap",c.getEmploymentGapMonths()+" months");factors.put("Notice Period",c.getNoticePeriodDays()+" days");factors.put("Identity",n(c.getIdentityStatus()).isBlank()?"PENDING":c.getIdentityStatus());factors.put("Education",n(c.getEducationStatus()).isBlank()?"PENDING":c.getEducationStatus());factors.put("Offer Letter",n(c.getOfferLetterStatus()).isBlank()?"PENDING":c.getOfferLetterStatus());m.put("riskFactors",factors);m.put("activities",List.of(Map.of("action","Candidate profile reviewed","createdAt",String.valueOf(c.getUpdatedAt())),Map.of("action","Risk score recalculated","createdAt",String.valueOf(c.getUpdatedAt()))));return m;}
 @PostMapping public Candidate create(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Candidate c){User u=auth.require(h);c.setId(null);c.setCreatedByUserId(u.getId());c.setCreatedByName(u.getName());c.setDuplicateEmail(repo.findAll().stream().anyMatch(x->x.getEmail()!=null&&x.getEmail().equalsIgnoreCase(c.getEmail())));c.setDuplicateMobile(repo.findAll().stream().anyMatch(x->Objects.equals(x.getMobileNumber(),c.getMobileNumber())));risk.calculate(c);Candidate saved=repo.save(c);syncEmbeddedDocuments(saved);risk.calculate(saved);saved=repo.save(saved);audit.audit(u.getName(),"CANDIDATE_CREATED","CANDIDATE",saved.getId().toString(),saved.getName()+" added");audit.notify("Candidate added",saved.getName()+" was added for verification.",saved.getRiskLevel());if("HIGH".equals(saved.getRiskLevel()))audit.notify("High-risk candidate",saved.getName()+" requires urgent review.","HIGH");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Candidate Added - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Profile Added","The profile was added by "+u.getName()+" and is now pending verification."));return saved;}
 @PutMapping("/{id}") public Candidate update(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody Candidate in){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();Long keep=c.getId();var created=c.getCreatedAt();assertCanModify(u,c);BeanUtils.copyProperties(in,c,"id","createdAt","updatedAt","createdByUserId","createdByName");c.setId(keep);c.setDuplicateEmail(repo.existsByEmailIgnoreCaseAndIdNot(c.getEmail(),id));c.setDuplicateMobile(repo.existsByMobileNumberAndIdNot(c.getMobileNumber(),id));risk.calculate(c);Candidate saved=repo.save(c);syncEmbeddedDocuments(saved);risk.calculate(saved);saved=repo.save(saved);audit.audit(u.getName(),"CANDIDATE_UPDATED","CANDIDATE",id.toString(),saved.getName()+" updated");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Candidate Updated - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Profile Updated","The profile information was revised by "+u.getName()+"."));return saved;}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();assertCanModify(u,c);repo.delete(c);audit.audit(u.getName(),"CANDIDATE_DELETED","CANDIDATE",id.toString(),c.getName()+" deleted");return ResponseEntity.noContent().build();}
 @PutMapping("/{id}/verification") public Candidate verify(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody Map<String,String>b){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();String employment=b.get("employmentStatus");String education=b.get("educationStatus");String identity=b.get("identityStatus");if("VERIFIED".equalsIgnoreCase(employment)&&(n(c.getCurrentCompany()).isBlank()||c.getJoiningDate()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current Company And Joining Date Are Required Before Employment Can Be Verified.");if("VERIFIED".equalsIgnoreCase(education)&&(n(c.getDegree()).isBlank()||n(c.getUniversity()).isBlank()||n(c.getGraduationYear()).isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Degree, University And Graduation Year Are Required Before Education Can Be Verified.");if("VERIFIED".equalsIgnoreCase(identity)){boolean aadhaar=!n(c.getAadhaarNumber()).isBlank()&&!n(c.getAadhaarDocumentData()).isBlank();boolean pan=!n(c.getPanNumber()).isBlank()&&!n(c.getPanDocumentData()).isBlank();boolean passport=n(c.getPassportNumber()).isBlank()||!n(c.getPassportDocumentData()).isBlank();if(!aadhaar||!pan||!passport)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Aadhaar And PAN Numbers With Uploaded Proof Are Required. Passport Proof Is Required When A Passport Number Is Entered.");}if(employment!=null)c.setEmploymentStatus(employment.toUpperCase(Locale.ROOT));if(education!=null)c.setEducationStatus(education.toUpperCase(Locale.ROOT));if(identity!=null)c.setIdentityStatus(identity.toUpperCase(Locale.ROOT));risk.calculate(c);Candidate saved=repo.save(c);audit.audit(u.getName(),"VERIFICATION_UPDATED","CANDIDATE",id.toString(),"Verification status changed");audit.notify("Verification completed",saved.getName()+" verification status is "+saved.getVerificationStatus()+".","LOW");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Verification Update - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Verification Status Updated","Current verification status: "+n(saved.getVerificationStatus())+". Employment: "+n(saved.getEmploymentStatus())+", Education: "+n(saved.getEducationStatus())+", Identity: "+n(saved.getIdentityStatus())+"."));return saved;}
 @PutMapping("/{id}/offer-verification") public Candidate verifyOffer(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody(required=false) Map<String,String>b){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Candidate Not Found."));if(b==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Verification Request Is Required.");String status=n(b.get("status")).trim().toUpperCase(Locale.ROOT);if(!Set.of("VERIFIED","PENDING","FAILED","MISMATCH").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose A Valid Offer Letter Status: Verified, Pending, Mismatch Or Failed.");boolean hasOffer=!n(c.getOfferLetterData()).isBlank()&&!n(c.getOfferLetterName()).isBlank();if(!"PENDING".equals(status)&&!hasOffer)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload And Save The Offer Letter Before Selecting A Verification Result.");if("VERIFIED".equals(status)){List<String> missing=new ArrayList<>();if(n(c.getOfferCandidateName()).isBlank())missing.add("Candidate Name On Offer");if(n(c.getOfferPosition()).isBlank())missing.add("Position On Offer");if(n(c.getOfferCompanyName()).isBlank())missing.add("Company Name On Offer");if(!missing.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Complete These Offer Details Before Verification: "+String.join(", ",missing)+".");List<String> mismatch=new ArrayList<>();if(!same(c.getName(),c.getOfferCandidateName()))mismatch.add("Candidate Name");if(!same(c.getPosition(),c.getOfferPosition()))mismatch.add("Position");if(!n(c.getCurrentCompany()).isBlank()&&!same(c.getCurrentCompany(),c.getOfferCompanyName()))mismatch.add("Company Name");if(!mismatch.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Offer Letter Mismatch Found In: "+String.join(", ",mismatch)+". Mark It As Mismatch Or Correct The Details.");}c.setOfferLetterStatus(status);c.setOfferVerificationRemarks(n(b.get("remarks")).trim());c.setOfferVerifiedBy(u.getName());c.setOfferVerifiedAt(java.time.LocalDateTime.now());risk.calculate(c);Candidate saved=repo.save(c);audit.audit(u.getName(),"OFFER_LETTER_"+status,"CANDIDATE",id.toString(),"Offer Letter Status Changed To "+status);audit.notify("Offer Letter "+status.substring(0,1)+status.substring(1).toLowerCase(),saved.getName()+" Offer Letter Review Was Completed.","FAILED".equals(status)||"MISMATCH".equals(status)?"HIGH":"LOW");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Offer Letter Update - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Offer Letter Verification Updated","Offer letter status: "+status+". Reviewed by "+u.getName()+"."+(n(saved.getOfferVerificationRemarks()).isBlank()?"":" Remarks: "+saved.getOfferVerificationRemarks())));return saved;}
 @PutMapping("/{id}/hire") public Candidate hire(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();if("HIRED".equalsIgnoreCase(c.getHiringStatus()))return c;c.setHiringStatus("HIRED");c.setHiredAt(java.time.LocalDateTime.now());c.setHiredBy(u.getName());Candidate saved=repo.save(c);audit.audit(u.getName(),"CANDIDATE_HIRED","CANDIDATE",id.toString(),saved.getName()+" marked as hired");audit.notify("Candidate hired",saved.getName()+" has been hired for "+saved.getPosition()+".","LOW");emailService.sendToAll(Arrays.asList(saved.getEmail(),u.getEmail()),"CrossCheck Hiring Update - "+saved.getName(),emailService.candidateMessage(saved.getName(),"Candidate Hired","You have been marked as hired for the position of "+saved.getPosition()+". Updated by "+u.getName()+"."));return saved;}
 @PostMapping("/{id}/documents") public DocumentRecord upload(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestParam String type,@RequestParam MultipartFile file)throws Exception{User u=auth.require(h);Candidate candidate=repo.findById(id).orElseThrow();if(file==null||file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose A Document To Upload.");if(file.getSize()>10L*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Document Must Be 10 MB Or Smaller.");String contentType=n(file.getContentType());if(!Set.of("application/pdf","image/jpeg","image/png","image/webp").contains(contentType))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Documents Must Be PDF, JPG, PNG Or WEBP.");Files.createDirectories(Path.of(uploadDir));String original=n(file.getOriginalFilename()).isBlank()?"document":file.getOriginalFilename();String safe=System.currentTimeMillis()+"-"+original.replaceAll("[^a-zA-Z0-9._-]","_");Path dest=Path.of(uploadDir,safe);file.transferTo(dest);DocumentRecord d=new DocumentRecord();d.setCandidateId(id);d.setType(n(type).trim().toUpperCase(Locale.ROOT));d.setFileName(original);d.setFilePath(dest.toAbsolutePath().toString());d.setContentType(contentType);d.setContentData(file.getBytes());d.setStatus("PENDING");DocumentRecord saved=docs.save(d);risk.calculate(candidate);repo.save(candidate);audit.audit(u.getName(),"DOCUMENT_UPLOADED","CANDIDATE",id.toString(),type+" uploaded and stored");emailService.sendToAll(Arrays.asList(candidate.getEmail(),u.getEmail()),"CrossCheck Document Update - "+candidate.getName(),emailService.candidateMessage(candidate.getName(),"Document Uploaded",type+" was uploaded by "+u.getName()+" and is pending review."));return saved;}
 @GetMapping("/{id}/documents/{documentId}/content") public ResponseEntity<byte[]> documentContent(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@PathVariable Long documentId)throws Exception{auth.require(h);DocumentRecord d=docs.findById(documentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document Not Found."));if(!Objects.equals(d.getCandidateId(),id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document Not Found.");byte[] data=d.getContentData();if((data==null||data.length==0)&&d.getFilePath()!=null&&Files.exists(Path.of(d.getFilePath())))data=Files.readAllBytes(Path.of(d.getFilePath()));if(data==null||data.length==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Stored Document Content Is Not Available.");return ResponseEntity.ok().header("Content-Disposition","inline; filename=\""+d.getFileName().replace("\"","")+"\"").contentType(org.springframework.http.MediaType.parseMediaType(n(d.getContentType()).isBlank()?"application/octet-stream":d.getContentType())).body(data);}
 @PutMapping("/{id}/documents/{documentId}/verification") public DocumentRecord verifyDocument(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@PathVariable Long documentId,@RequestBody Map<String,String> body){User u=auth.require(h);Candidate candidate=repo.findById(id).orElseThrow();DocumentRecord d=docs.findById(documentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Document Not Found."));if(!Objects.equals(d.getCandidateId(),id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Document Not Found.");String status=n(body.get("status")).trim().toUpperCase(Locale.ROOT);if(!Set.of("VERIFIED","PENDING","REJECTED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose Verified, Pending Or Rejected.");if("VERIFIED".equals(status)&&(d.getContentData()==null||d.getContentData().length==0)&&n(d.getFilePath()).isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Document Content Is Missing And Cannot Be Verified.");d.setStatus(status);d.setVerifiedBy(u.getName());d.setVerifiedAt(java.time.LocalDateTime.now());DocumentRecord saved=docs.save(d);risk.calculate(candidate);repo.save(candidate);audit.audit(u.getName(),"DOCUMENT_"+status,"CANDIDATE",id.toString(),d.getType()+" marked "+status);return saved;}
 private void syncEmbeddedDocuments(Candidate c){upsertEmbedded(c,"AADHAAR",c.getAadhaarDocumentName(),c.getAadhaarDocumentData());upsertEmbedded(c,"PAN",c.getPanDocumentName(),c.getPanDocumentData());upsertEmbedded(c,"PASSPORT",c.getPassportDocumentName(),c.getPassportDocumentData());upsertEmbedded(c,"OFFER_LETTER",c.getOfferLetterName(),c.getOfferLetterData());}
 private void upsertEmbedded(Candidate c,String type,String fileName,String dataUrl){if(n(fileName).isBlank()||n(dataUrl).isBlank())return;try{int comma=dataUrl.indexOf(',');String meta=comma>0?dataUrl.substring(0,comma):"";String encoded=comma>=0?dataUrl.substring(comma+1):dataUrl;byte[] bytes=Base64.getDecoder().decode(encoded);String contentType=meta.startsWith("data:")&&meta.contains(";")?meta.substring(5,meta.indexOf(';')):"application/octet-stream";DocumentRecord d=docs.findByCandidateIdOrderByUploadedAtDesc(c.getId()).stream().filter(x->type.equalsIgnoreCase(x.getType())).findFirst().orElseGet(DocumentRecord::new);d.setCandidateId(c.getId());d.setType(type);d.setFileName(fileName);d.setContentType(contentType);d.setContentData(bytes);d.setFilePath(null);if(d.getId()==null)d.setStatus("PENDING");docs.save(d);}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,type.replace('_',' ')+" File Data Is Invalid.");}}
 private void assertCanModify(User u,Candidate c){boolean admin="ADMIN".equalsIgnoreCase(u.getRole());boolean owner=c.getCreatedByUserId()!=null&&Objects.equals(c.getCreatedByUserId(),u.getId());if(!admin&&!owner)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only The User Who Added This Candidate Or An Admin Can Edit Or Delete It.");}
 private boolean same(String a,String b){return n(a).trim().equalsIgnoreCase(n(b).trim());}
 private String n(String s){return s==null?"":s;}
}
